	'bulk.merges.refused.missing': { de: 'Mindestens einen der beiden Kontakte gibt es nicht mehr, deshalb lässt sich die Zusammenführung hier nicht zurücknehmen.', en: 'At least one of the two contacts no longer exists, so the merge cannot be taken back here.' },
