	'bulk.merges.refused.not_in_effect': { de: 'Diese Zusammenführung wirkt nicht mehr. Sie wurde schon zurückgenommen, oder der Kontakt wurde seither anders zusammengeführt.', en: 'This merge is no longer in effect. It was taken back already, or the contact was merged elsewhere since.' },
	'bulk.merges.refused.chained_named': { de: 'Der Kontakt, in den diese Zusammenführung geführt hat, wurde seither weiter zusammengeführt. Nimm zuerst die Zusammenführung „{dup2}“ → „{canonical2}“ zurück. Danach versuch es hier noch einmal.', en: 'The contact this merge led to has since been merged onward. Take back the merge “{dup2}” → “{canonical2}” first. Then try this one again.' },
	'bulk.merges.refused.chained_unnamed': { de: 'Der Kontakt, in den diese Zusammenführung geführt hat, wurde seither weiter zusammengeführt. Diese neuere Zusammenführung lässt sich hier nicht zurücknehmen, deshalb auch diese nicht.', en: 'The contact this merge led to has since been merged onward. That newer merge cannot be taken back here, so this one cannot either.' },
	'bulk.merges.refused.chained_changed': { de: 'Der Kontakt, in den diese Zusammenführung geführt hat, wurde seither weiter zusammengeführt. Seit deinem Versuch hat sich die Liste geändert. Versuch es noch einmal.', en: 'The contact this merge led to has since been merged onward. The list has changed since you tried. Try again.' },
	'bulk.merges.refused.unavailable': { de: 'Diese Zusammenführung hat Datenzeilen oder Gespräche verschoben, und dieser Teil deiner Instanz war beim Versuch nicht verfügbar. Es wurde nichts zurückgenommen.', en: 'This merge moved data rows or conversations, and that part of your instance was not available when you tried. Nothing was taken back.' },
